def nth_newman_shanks_williams(n):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def is_newman_shanks_williams(x):
        return is_prime(x) and x**0.5 == int(x**0.5)

    def factorial(n):
        if n == 0:
            return 1
        else:
            return n * factorial(n-1)

    def is_prime_factorization(n):
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                if is_newman_shanks_williams(i) and i**0.5 == int(i**0.5):
                    return True
                if is_prime(i) and is_prime(n // i):
                    return True
        return False

    def williams_prime_factorization(n):
        if is_prime_factorization(n):
            return n
        else:
            p = 2
            while p**2 <= n:
                if is_prime_factorization(p**2):
                    return p**2
                p += 1
            return None

    return williams_prime_factorization(n)
